const LEASE: Duration = Duration::from_millis(900);
const POLL: Duration = Duration::from_millis(25);
const SETTLE_BUDGET: Duration = Duration::from_secs(30);
const ABSENCE_BUDGET: Duration = Duration::from_secs(2);
const RUN: LoserPolicy = LoserPolicy::RunToCompletion;

/// The leaf tools the admitting opener's children call. A deferred leaf
/// parks on a completion key, a spend leaf bills a managed call and declares
/// intents, a gate leaf waits on the cooperative token, and an observe leaf
/// carries a grant — one observable lane of the lent deployment each.
const TOOL_OBSERVE: &str = "tool:a_observe";
const TOOL_SPEND: &str = "tool:a_spend";
const TOOL_DEFER: &str = "tool:a_defer";
const TOOL_GATE: &str = "tool:a_gate";
/// The only tool B's own deployment serves honestly: its offered children
/// never run, so this exists only to keep B's registry non-empty.
const TOOL_B_PROBE: &str = "tool:b_probe";

const INTENT_EVENT_TYPE: &str = "differential.intent";

/// The number of children in the group: one per leaf lane.
const ARITY: usize = 4;

// =============================================================================
// Observation
// =============================================================================

/// What one leaf execution reported back.
#[derive(Clone, Debug)]
struct LeafExecution {
    /// The tool name the leaf was invoked under.
    tool: String,
    /// The session the attempt context was bound to — the child's recorded
    /// session when the driver honoured the retained request.
    session_id: String,
    /// The one-based attempt number.
    attempt: u32,
    /// The execution binding the attempt carried — the grant's, for the
    /// granted leaf.
    execution_binding: serde_json::Value,
    /// The enclosing process the attempt's context reported.
    enclosing_process: Option<String>,
}

/// The shared observation surface between a provider and the oracle.
#[derive(Default)]
struct Observation {
    /// Executions in the order the runtime produced them.
    executions: Mutex<Vec<LeafExecution>>,
    /// The completion key each deferrable leaf took, keyed by call id.
    parked_keys: Mutex<HashMap<String, AwaitEventKey>>,
    /// Signalled whenever `parked_keys` gains an entry.
    parked: Notify,
    /// How many gate leaves have entered and parked on their token.
    gate_entered: AtomicUsize,
}

impl Observation {
    fn record(&self, call: &lash_core::ToolCall<'_>) {
        let context = call.context;
        self.executions.lock_recover().push(LeafExecution {
            tool: call.name().to_string(),
            session_id: context.session_id().to_string(),
            attempt: context.attempt_number(),
            execution_binding: context.tool_execution_binding().clone(),
            enclosing_process: context.enclosing_process().map(str::to_string),
        });
    }

    fn executions(&self) -> Vec<LeafExecution> {
        self.executions.lock_recover().clone()
    }

    fn park(&self, call_id: &str, key: AwaitEventKey) {
        self.parked_keys
            .lock_recover()
            .insert(call_id.to_string(), key);
        self.parked.notify_waiters();
    }

    /// Waits until the leaf under `call_id` has parked, and answers its key.
    async fn parked_key(&self, call_id: &str) -> AwaitEventKey {
        tokio::time::timeout(SETTLE_BUDGET, async {
            loop {
                if let Some(key) = self.parked_keys.lock_recover().get(call_id).cloned() {
                    return key;
                }
                self.parked.notified().await;
            }
        })
        .await
        .unwrap_or_else(|_| {
            panic!("the deferred leaf under `{call_id}` never parked on a completion key")
        })
    }
}

// =============================================================================
// The opener deployments — every checklist field, per side
// =============================================================================

/// One opener's live deployment: the real value it supplies for every
/// [`RebindField`], plus the request-side facts the retained authority is
/// built from.
///
/// `axis_value` is the checklist's exhaustive conscience — one arm per field,
/// no catch-all, so a field added to `REBIND_FIELDS` fails compilation until
/// a human decides what each opener supplies for it. This struct holds what
/// those arms describe and `build_dispatch` wires them into a real
/// `ToolDispatchContext`.
struct OpenerDeployment {
    /// `RebindField::Plugins` — the factories the plugin session is built from.
    plugin_factories: Vec<Arc<dyn PluginFactory>>,
    /// Recorded so the axis can name the composition without introspection.
    plugin_ids: &'static str,
    /// `RebindField::Tools` — the leaf provider.
    provider: Arc<ProfileProvider>,
    /// `RebindField::ToolRegistry` — the registry the dispatch consults.
    tool_registry: Arc<ToolRegistry>,
    /// `RebindField::ToolCatalog` — the catalog definitions the context holds
    /// (rebound per child from the recorded admission at run time; the lent
    /// half still differs so a leak would be visible in routing).
    catalog_definitions: Vec<ToolDefinition>,
    /// `RebindField::{Sessions, SessionLifecycle, SessionGraph}` — the side's
    /// own session host object.
    session_host: Arc<MockSessionManager>,
    /// `RebindField::Processes` — the process service over the side's own
    /// registry.
    processes: Arc<dyn ProcessService>,
    /// The registry `processes` serves, kept so intent realization can be
    /// observed on A's and proven absent on B's.
    process_registry: Arc<TestLocalProcessRegistry>,
    /// `RebindField::TriggerRouter` — A none, B a real router over its own
    /// trigger store.
    trigger_router: Option<TriggerRouter>,
    /// `RebindField::ProcessDefinitions` — A none, B a real empty registry.
    process_definitions: Option<Arc<dyn lash_core::ProcessDefinitionRegistry>>,
    /// `RebindField::ProcessEngines` — A empty, B the fixture engine.
    process_engines: ProcessEngineRegistry,
    /// `RebindField::DirectCompletions` — the log this side's client bills
    /// into, and the canned completion it answers with.
    completion_log: Arc<Mutex<Vec<String>>>,
    completion_canned: DirectCompletion,
    /// `RebindField::ParentInvocation` — the dispatch's installed parent.
    parent_invocation: RuntimeInvocation,
    /// `RebindField::ExecutionEnvSpec` — the side's own environment.
    env_spec: ProcessExecutionEnvSpec,
    env_ref: ProcessExecutionEnvRef,
    /// `RebindField::SessionId` / `AgentFrameId` — the rebound pair, also
    /// carried by the request.
    session_id: SessionId,
    agent_frame_id: FrameNodeId,
    /// `RebindField::AttachmentStore` / `AttachmentSourcePolicy` — the side's
    /// own instances.
    attachment_store: Arc<SessionAttachmentStore>,
    attachment_source_policy: Arc<dyn AttachmentSourcePolicy>,
    /// `RebindField::TurnContext` — the side's own turn context.
    turn_context: TurnContext,
    /// `RebindField::Clock` — A the system clock, B a test clock.
    clock: Arc<dyn lash_core::Clock>,
    /// The request-side facts: the opener arm, the admitted scope pair, the
    /// recorded cancellation authority, the enclosing process, the completion
    /// routing.
    opener: EffectOpener,
    admitted_scope: AdmittedScope,
    routing: ToolChildCompletionRouting,
    enclosing_process: Option<ProcessRef>,
    /// A label for assertions: "a" or "b".
    tag: &'static str,
}

impl OpenerDeployment {
    /// Builds the dispatch context this opener lends its children — a real
    /// `ToolDispatchContext`, field by field. `provider` overrides
    /// `self.provider` for the `tools` field, so the crash world can lend
    /// A's deployment with leaf bodies that park instead of serving. The
    /// literal and `axis_value`'s match fail to compile together the day the
    /// checklist grows.
    #[expect(
        clippy::expect_used,
        reason = "test support: a plugin session builds over these factories; a refusal panics the harness with its case name by design"
    )]
    fn build_dispatch(
        &self,
        provider: Arc<dyn ToolProvider>,
        controller: ScopedEffectController<'static>,
    ) -> Arc<ToolDispatchContext<'static>> {
        let plugins = PluginHost::new(self.plugin_factories.clone())
            .build_session(&self.session_id)
            .expect("the side's plugin session builds");
        let (event_tx, _event_rx) = tokio::sync::mpsc::channel(1);
        let completion_log = Arc::clone(&self.completion_log);
        let canned = self.completion_canned.clone();
        Arc::new(ToolDispatchContext {
            plugins,
            tools: provider,
            tool_registry: Some(Arc::clone(&self.tool_registry)),
            tool_catalog: Arc::new(ToolCatalog::from_tool_definitions(
                self.catalog_definitions.clone(),
            )),
            sessions: self.session_host.clone(),
            session_lifecycle: self.session_host.clone(),
            session_graph: self.session_host.clone(),
            processes: Arc::clone(&self.processes),
            trigger_router: self.trigger_router.clone(),
            process_definitions: self.process_definitions.clone(),
            process_engines: self.process_engines.clone(),
            effect_controller: RuntimeEffectControllerHandle::borrowed(controller),
            direct_completions: DirectCompletionClient::from_fn(move |request, source| {
                completion_log
                    .lock_recover()
                    .push(format!("{source}:{}", request.model));
                Ok(canned.clone())
            }),
            parent_invocation: Some(self.parent_invocation.clone()),
            execution_env_spec: self.env_spec.clone(),
            session_id: self.session_id.clone(),
            agent_frame_id: self.agent_frame_id.clone(),
            event_tx,
            checkpoint_messages: CheckpointMessageBuffer::default(),
            trigger_outcomes: ToolTriggerOutcomeBuffer::default(),
            attachment_store: Arc::clone(&self.attachment_store),
            attachment_source_policy: Arc::clone(&self.attachment_source_policy),
            turn_context: self.turn_context.clone(),
            clock: Arc::clone(&self.clock),
        })
    }

    /// Registers this opener's context as live in `installed`'s registry,
    /// returning the registration guard — the registration's whole lifetime.
    /// `provider` is what the lent dispatch serves as `tools`.
    #[expect(
        clippy::expect_used,
        reason = "test support: the dispatch context is 'static and the scope binds; a refusal panics the harness with its case name by design"
    )]
    fn register_opener(
        &self,
        host: &Arc<SqliteEffectHost>,
        installed: &Arc<ToolChildHost>,
        provider: Arc<dyn ToolProvider>,
        cooperative: &CancellationToken,
    ) -> (LiveOpenerGuard, LiveOpenerContext) {
        let controller = host
            .scoped_static(self.admitted_scope.clone())
            .expect("the host lends a scoped controller")
            .expect("this host hands out owned scoped controllers");
        let dispatch = self.build_dispatch(provider, controller);
        let lent_controller = host
            .scoped_static(self.admitted_scope.clone())
            .expect("the host lends a scoped controller")
            .expect("this host hands out owned scoped controllers");
        let (event_tx, mut event_rx) = tokio::sync::mpsc::channel(64);
        let context = LiveOpenerContext::capture_with_event_sender(
            &dispatch,
            lent_controller,
            event_tx,
            cooperative.clone(),
        );
        let (guard, ended) = installed
            .openers()
            .register(self.opener.clone(), context.clone());
        // The registration owns the sender's lifetime: the forwarder ends
        // when the entry leaves the registry, exactly as the turn path's does.
        tokio::spawn(async move {
            tokio::select! {
                _ = ended.cancelled() => {}
                _ = async { while event_rx.recv().await.is_some() {} } => {}
            }
        });
        (guard, context)
    }
}

/// The fixture-visible value one side supplies for `field`, as a string a
/// failing assert can name.
///
/// **One arm per checklist line, no catch-all.** A `RebindField` added to
/// [`REBIND_FIELDS`] is a compile error here until a human decides what each
/// opener supplies for it — the exhaustive match is the fixture contract the
/// review requires, not a convenience. `Rebound` fields read their value out
/// of the retained request, because the request is the authority the child
/// runs under; `Lent` fields read the deployment object itself; `Fresh`
/// fields carry no recorded fact and answer a constant.
#[expect(
    clippy::expect_used,
    reason = "test support: every request and deployment value serializes; a refusal panics the harness with its case name by design"
)]
fn axis_value(
    deployment: &OpenerDeployment,
    request: &ToolChildRequest,
    field: RebindField,
) -> String {
    match field {
        // --- Lent: the live deployment wiring the child borrows. ---
        RebindField::Plugins => deployment.plugin_ids.to_string(),
        RebindField::Tools => deployment.provider.tag.to_string(),
        RebindField::ToolRegistry => format!("{:p}", Arc::as_ptr(&deployment.tool_registry)),
        RebindField::Sessions => format!("{:p}", Arc::as_ptr(&deployment.session_host)),
        RebindField::SessionLifecycle => {
            format!("lifecycle:{:p}", Arc::as_ptr(&deployment.session_host))
        }
        RebindField::SessionGraph => {
            format!("graph:{:p}", Arc::as_ptr(&deployment.session_host))
        }
        RebindField::Processes => format!("{:p}", Arc::as_ptr(&deployment.process_registry)),
        RebindField::TriggerRouter => format!("router:{}", deployment.trigger_router.is_some()),
        RebindField::ProcessDefinitions => {
            format!("definitions:{}", deployment.process_definitions.is_some())
        }
        RebindField::ProcessEngines => format!("engines:{}", deployment.tag),
        RebindField::EventTx => format!("event-tx:{}", deployment.tag),
        RebindField::AttachmentStore => {
            format!("{:p}", Arc::as_ptr(&deployment.attachment_store))
        }
        RebindField::AttachmentSourcePolicy => {
            format!("{:p}", Arc::as_ptr(&deployment.attachment_source_policy))
        }
        RebindField::TurnContext => format!("turn-context:{}", deployment.tag),
        RebindField::Clock => format!("{:p}", Arc::as_ptr(&deployment.clock)),
        // --- Rebound: the recorded request is the authority. ---
        RebindField::ToolCatalog => {
            serde_json::to_string(&request.admission).expect("the admission serializes")
        }
        RebindField::EffectController => format!("{:?}", request.scope.admitted_scope),
        RebindField::DirectCompletions => serde_json::to_string(&request.completion_routing)
            .expect("the completion routing serializes"),
        RebindField::ParentInvocation => serde_json::to_string(&request.attempt_identity)
            .expect("the attempt identity serializes"),
        RebindField::ExecutionEnvSpec => request.execution_env.as_str().to_string(),
        RebindField::SessionId => request.scope.session_id.to_string(),
        RebindField::AgentFrameId => request.scope.agent_frame_id.to_string(),
        // --- Fresh: the child mints its own buffers; nothing to differ. ---
        RebindField::CheckpointMessages => "fresh".to_string(),
        RebindField::TriggerOutcomes => "fresh".to_string(),
    }
}

// =============================================================================
// The leaf provider
// =============================================================================

/// One opener's tool provider. In `serve` mode it runs the four leaf lanes
/// and records every execution; in `park` mode a body reports it started and
/// then never returns — the crash world's in-flight children. In `impostor`
/// mode (B's deployment under the leak) it answers any tool id with a
/// B-tagged output, so a retained A request executed under B's context is
/// observable as B's impl running A's work.
struct ProfileProvider {
    tag: &'static str,
    park: bool,
    impostor: bool,
    observation: Arc<Observation>,
    /// The session the intents leaf declares on (the side's own).
    session_id: SessionId,
    /// The process the intents leaf emits to, registered on the side's own
    /// registry.
    intent_target: ProcessId,
}

/// One definition per A-side leaf lane, plus the retry policy the spend leaf
/// needs: two billed attempts inside one journaled retry.
fn leaf_definitions() -> Vec<ToolDefinition> {
    [TOOL_OBSERVE, TOOL_SPEND, TOOL_DEFER, TOOL_GATE]
        .into_iter()
        .map(|id| {
            let name = id.trim_start_matches("tool:");
            let mut definition = ToolDefinition::raw(
                id,
                name,
                format!("differential leaf {name}"),
                ToolDefinition::default_input_schema(),
                serde_json::json!({ "type": "object", "additionalProperties": true }),
            );
            if id == TOOL_SPEND {
                definition = definition.with_retry_policy(ToolRetryPolicy::safe(3, 0, 0));
            }
            definition
        })
        .collect()
}

/// B's catalog: its own probe tool — B's deployment never serves A's leaves
/// through the catalog, which is what makes a leaked execution legible.
fn b_catalog_definitions() -> Vec<ToolDefinition> {
    vec![ToolDefinition::raw(
        TOOL_B_PROBE,
        TOOL_B_PROBE.trim_start_matches("tool:"),
        "differential impostor probe",
        ToolDefinition::default_input_schema(),
        serde_json::json!({ "type": "object", "additionalProperties": true }),
    )]
}

#[async_trait::async_trait]
impl ToolProvider for ProfileProvider {
    fn tool_manifests(&self) -> Vec<ToolManifest> {
        let mut definitions = leaf_definitions();
        definitions.extend(b_catalog_definitions());
        definitions
            .iter()
            .map(|definition| definition.manifest())
            .collect()
    }

    fn resolve_contract(&self, name: &str) -> Option<Arc<ToolContract>> {
        leaf_definitions()
            .into_iter()
            .chain(b_catalog_definitions())
            .find(|definition| definition.manifest().name == name)
            .map(|definition| Arc::new(definition.contract()))
    }

    fn attempt_may_defer(&self, tool_id: &ToolId) -> bool {
        *tool_id == ToolId::from(TOOL_DEFER)
    }

    async fn execute(&self, call: lash_core::ToolCall<'_>) -> ToolAttemptOutcome {
        let name = call.name().to_string();
        self.observation.record(&call);
        if self.park {
            // The crash world's children: in flight forever.
            std::future::pending::<()>().await;
            unreachable!("a parked leaf body is never polled to completion");
        }
        if self.impostor {
            // B's deployment under the leak: any retained request is served by
            // B's impl, observably tagged.
            return ToolAttemptOutcome::done_without_intents(ToolOutcomeDone::ok(
                serde_json::json!({ "impostor": self.tag, "tool": name }),
            ));
        }
        let context = call.context;
        match name.as_str() {
            "a_observe" => ToolAttemptOutcome::done_without_intents(ToolOutcomeDone::ok(
                serde_json::json!({ "impl": "a", "leaf": "observe" }),
            )),
            "a_spend" => {
                // The managed-LLM spend is billed through the lent completion
                // client on *every* attempt — the failed first attempt's spend
                // is a fact the ledger must carry (FIG-3429 item 7's class).
                if let Err(error) = context
                    .direct_completions()
                    .complete(
                        DirectRequest::text("model-a", "the spend the ledger must carry"),
                        "a-spend",
                    )
                    .await
                {
                    return ToolOutcome::err_fmt(format!(
                        "the spend leaf's direct completion failed: {error}"
                    ))
                    .into();
                }
                if context.attempt_number() == 1 {
                    ToolOutcome::failure(ToolFailure::safe_retry(
                        ToolFailureClass::Internal,
                        "a_spend_first_attempt",
                        "the first attempt is journaled as a retryable failure",
                        Some(0),
                    ))
                    .into()
                } else {
                    ToolAttemptOutcome::done(
                        ToolOutcomeDone::ok(serde_json::json!({ "impl": "a", "leaf": "spend" })),
                        ToolIntents::v3(vec![
                            ToolIntent::StartProcess(Box::new(StartProcessIntent {
                                session_id: self.session_id.clone(),
                                declaration: ProcessStartDeclaration::external(
                                    ProcessOriginator::host(),
                                    serde_json::json!({ "impl": "a", "leaf": "spend" }),
                                    ProcessLifecyclePolicy::new(
                                        ParentScope::Host,
                                        OnParentEnd::Abandon,
                                    ),
                                ),
                            })),
                            ToolIntent::EmitProcessEvent(EmitProcessEventIntent {
                                session_id: self.session_id.clone(),
                                process_id: self.intent_target.clone(),
                                event_type: INTENT_EVENT_TYPE.to_string(),
                                payload: serde_json::json!({ "impl": "a", "leaf": "spend" }),
                            }),
                        ]),
                    )
                }
            }
            "a_defer" => match context.completion_key() {
                Ok(key) => {
                    let call_id = context
                        .tool_call_id()
                        .unwrap_or("missing-call-id")
                        .to_string();
                    self.observation.park(&call_id, key);
                    ToolAttemptOutcome::pending(PendingCompletion::new())
                }
                Err(error) => ToolOutcome::err_fmt(format!(
                    "the deferred leaf could not take a completion key: {error}"
                ))
                .into(),
            },
            "a_gate" => match context.cancellation_token() {
                Some(token) => {
                    self.observation.gate_entered.fetch_add(1, Ordering::SeqCst);
                    token.cancelled().await;
                    ToolOutcome::cancelled("the opener's cooperative gate stopped this attempt")
                        .into()
                }
                None => {
                    ToolOutcome::err_fmt("the gate leaf found no cooperative cancellation token")
                        .into()
                }
            },
            other => {
                ToolOutcome::err_fmt(format!("the differential has no A-side leaf named {other}"))
                    .into()
            }
        }
    }
}

/// The canned managed-LLM completion each side's client answers with. The
/// token counts differ per side so the settlement's ledger says *whose*
/// client was billed, not just that billing happened.
fn canned_completion(tag: &'static str, input: i64, output: i64) -> DirectCompletion {
    DirectCompletion {
        text: format!("{tag} direct completion"),
        usage: lash_core::TokenUsage {
            input_tokens: input,
            output_tokens: output,
            ..lash_core::TokenUsage::default()
        },
        llm_call: LlmCallRecord {
            call_id: LlmCallId(format!("{tag}-direct-call")),
            label: None,
            replay_drops: Vec::new(),
            attempts: vec![AttemptRecord {
                ordinal: 1,
                started_at: 0,
                duration: Duration::ZERO,
                outcome: AttemptOutcome::Completed,
                protocol_position: ProtocolPosition::ResponseObserved,
                retry_budget_consumed: false,
                retry_decision: None,
                error: None,
                evidence: None,
                generation_disposition: None,
                usage: Some(lash_core::llm::types::LlmUsage {
                    input_tokens: input,
                    output_tokens: output,
                    cache_read_input_tokens: 0,
                    cache_write_input_tokens: 0,
                    reasoning_output_tokens: 0,
                }),
                usage_disposition: AttemptUsageDisposition::default(),
            }],
        },
    }
}

// =============================================================================
// Requests and groups
// =============================================================================

/// The request one retained child carries — the whole of the authority it
/// was admitted under.
fn request(
    side: &OpenerDeployment,
    call_id: &str,
    tool_id: &str,
    admission: ToolChildAdmission,
    cancellation: Option<TurnControlBindingId>,
) -> ToolChildRequest {
    let tool_name = tool_id.trim_start_matches("tool:");
    let call = PreparedToolCall::from_parts(
        call_id,
        ToolId::from(tool_id),
        tool_name,
        serde_json::json!({ "side": side.tag }),
        None,
        serde_json::Value::Null,
    );
    let mut request = ToolChildRequest::new(
        call,
        admission,
        ToolAttemptEffectIdentity::Scalar {
            parent: Some(side.parent_invocation.clone()),
        },
        ToolChildScope {
            opener: side.opener.clone(),
            admitted_scope: side.admitted_scope.clone(),
            session_id: side.session_id.clone(),
            agent_frame_id: side.agent_frame_id.clone(),
        },
        side.env_ref.clone(),
        side.routing.clone(),
    );
    if let Some(binding) = cancellation {
        request = request.with_cancellation_authority(binding);
    }
    if let Some(process) = &side.enclosing_process {
        request = request.with_enclosing_process(process.clone());
    }
    request
}

/// A's four retained children: one leaf lane each.
fn requests_a(
    side: &OpenerDeployment,
    group_key: &str,
    cancellation: Option<TurnControlBindingId>,
) -> Vec<ToolChildRequest> {
    let definitions = leaf_definitions();
    [TOOL_OBSERVE, TOOL_SPEND, TOOL_DEFER, TOOL_GATE]
        .into_iter()
        .map(|tool_id| {
            let admission = if tool_id == TOOL_OBSERVE {
                // A grant: authority the live catalog never saw, recorded in
                // the request alone.
                let definition = definitions
                    .iter()
                    .find(|definition| definition.manifest().id == ToolId::from(TOOL_OBSERVE))
                    .unwrap_or_else(|| unreachable!("the observe leaf has a definition"));
                ToolChildAdmission::Granted {
                    grant: Box::new(
                        ToolExecutionGrant::from_definition(definition.clone())
                            .with_source_id("source-a")
                            .with_execution_binding(serde_json::json!({ "opener": "a" })),
                    ),
                }
            } else {
                let manifest = definitions
                    .iter()
                    .find(|definition| definition.manifest().id == ToolId::from(tool_id))
                    .unwrap_or_else(|| unreachable!("every leaf has a definition"))
                    .manifest();
                ToolChildAdmission::Catalog {
                    manifest: Box::new(manifest),
                }
            };
            request(
                side,
                &format!("{group_key}-call-{}", position_of(tool_id)),
                tool_id,
                admission,
                cancellation.clone(),
            )
        })
        .collect()
}

/// B's offered children: same replay-key positions, B's own requests.
fn requests_b(
    side: &OpenerDeployment,
    group_key: &str,
    cancellation: Option<TurnControlBindingId>,
) -> Vec<ToolChildRequest> {
    let manifest = b_catalog_definitions()
        .first()
        .unwrap_or_else(|| unreachable!("the probe tool has a definition"))
        .manifest();
    (0..ARITY)
        .map(|position| {
            request(
                side,
                &format!("{group_key}-bcall-{position}"),
                TOOL_B_PROBE,
                ToolChildAdmission::Catalog {
                    manifest: Box::new(manifest.clone()),
                },
                cancellation.clone(),
            )
        })
        .collect()
}

fn position_of(tool_id: &str) -> usize {
    [TOOL_OBSERVE, TOOL_SPEND, TOOL_DEFER, TOOL_GATE]
        .iter()
        .position(|id| *id == tool_id)
        .unwrap_or_else(|| unreachable!("a leaf tool id"))
}

fn child_key(group_key: &str, position: usize) -> String {
    format!("{group_key}:child:{position}")
}

#[expect(
    clippy::expect_used,
    reason = "test support: the fixture's addresses are valid by construction; a refusal panics the harness with its case name by design"
)]
fn child_envelope(
    scope: &ExecutionScope,
    group_key: &str,
    position: usize,
    request: &ToolChildRequest,
) -> RuntimeEffectEnvelope {
    RuntimeEffectEnvelope::new(
        RuntimeEffectInvocation::new(
            EffectAddress::new(scope.clone(), child_key(group_key, position))
                .expect("valid group-child address"),
            RuntimeAttribution::none(),
            "effect",
        ),
        RuntimeEffectCommand::ToolInvocation {
            request: Box::new(request.clone()),
        },
    )
}

/// The group over per-position requests — replay keys identical whichever
/// side's requests built them.
#[expect(
    clippy::expect_used,
    reason = "test support: the fixture's addresses are valid by construction; a refusal panics the harness with its case name by design"
)]
fn group(scope: &ExecutionScope, key: &str, requests: &[ToolChildRequest]) -> RuntimeEffectGroup {
    RuntimeEffectGroup::try_new(
        RuntimeEffectInvocation::new(
            EffectAddress::new(scope.clone(), format!("{key}:group")).expect("valid group address"),
            RuntimeAttribution::none(),
            "group",
        ),
        key,
        requests
            .iter()
            .enumerate()
            .map(|(position, request)| child_envelope(scope, key, position, request))
            .collect(),
        GroupWakePolicy::All,
        RUN,
    )
    .expect("a group with at least one child assembles")
}

