// Worlds
// =============================================================================

/// One host over the shared journal.
#[expect(
    clippy::expect_used,
    reason = "test support: a fresh temp journal opens; a refusal panics the harness with its case name by design"
)]
async fn world(path: &Path) -> Arc<SqliteEffectHost> {
    Arc::new(
        SqliteEffectHost::open_with_options(
            path,
            SqliteEffectReplayOptions {
                lease_timings: LeaseTimings::new(LEASE, LEASE / 3)
                    .expect("a lease at least three renew intervals wide"),
                drain_budget: Default::default(),
            },
        )
        .await
        .expect("the SQLite effect host opens"),
    )
}

/// Installs the tool-child host on `host`, returning the installed resolver.
#[expect(
    clippy::expect_used,
    reason = "test support: a tier that routes tool children installs the child host; a refusal panics the harness with its case name by design"
)]
fn install_child_host(
    host: &Arc<SqliteEffectHost>,
    process_env_store: &Arc<dyn lash_core::ProcessExecutionEnvStore>,
) -> Arc<ToolChildHost> {
    let dyn_host: Arc<dyn EffectHost> = Arc::clone(host) as Arc<dyn EffectHost>;
    host.install_tool_child_host(ToolChildHost::new(&dyn_host, Arc::clone(process_env_store)))
        .expect("a host that routes tool children installs the child host")
}

/// The cancellation authority the opener records on a child at group
/// formation: what this host derives for the child's admitted scope — or
/// `None` where the controller participates locally.
#[expect(
    clippy::expect_used,
    reason = "test support: a durable participant's binding derives; a refusal panics the harness with its case name by design"
)]
async fn recorded_cancellation_authority(
    host: &Arc<SqliteEffectHost>,
    admitted: &AdmittedScope,
) -> Option<TurnControlBindingId> {
    let scoped = host.scoped(admitted.clone()).expect("the scope binds");
    if scoped
        .controller()
        .turn_control_participation()
        .await
        .expect("participation resolves")
        != lash_core::runtime::effect::TurnControlParticipation::DurableJournaled
    {
        return None;
    }
    let binding = host
        .turn_control_binding(&scoped)
        .await
        .expect("a durable participant's binding derives");
    Some(
        TurnControlBindingId::new(binding.binding_id().to_string())
            .expect("the host's binding id is valid"),
    )
}

/// The crash: open the group under A's live opener with leaf bodies that
/// park, wait until every child is in flight, and destroy the runtime — the
/// shape a killed worker leaves: claimed, journaled children owned by
/// nobody.
#[expect(
    clippy::expect_used,
    reason = "test support: the crashing phase's thread, runtime and group open are fixture facts; a refusal panics the harness with its case name by design"
)]
fn crash_opening(
    path: &Path,
    group: RuntimeEffectGroup,
    admitted: AdmittedScope,
    side_a: &OpenerDeployment,
    park_provider: Arc<ProfileProvider>,
    process_env_store: Arc<dyn lash_core::ProcessExecutionEnvStore>,
    entered: Arc<Observation>,
) {
    let path = path.to_path_buf();
    // A scoped thread borrows `side_a` — the crashing process's registration
    // is a fact of this test's deployment, not a second fixture. The runtime
    // built inside dies with the thread, which is what makes the crash real:
    // the parked leaf bodies are aborted mid-poll.
    std::thread::scope(|s| {
        s.spawn(move || {
            let runtime = tokio::runtime::Builder::new_multi_thread()
                .worker_threads(2)
                .enable_all()
                .build()
                .expect("the crashing process gets a runtime of its own");
            runtime.block_on(async move {
                let world = world(&path).await;
                let installed = install_child_host(&world, &process_env_store);
                let _guard = side_a.register_opener(
                    &world,
                    &installed,
                    park_provider,
                    &CancellationToken::new(),
                );
                let scoped = world.scoped(admitted).expect("the group scope binds");
                let _handle = scoped
                    .controller()
                    .open_effect_group(group)
                    .await
                    .expect("the group opens under the live opener");
                let deadline = std::time::Instant::now() + SETTLE_BUDGET;
                while entered.executions().len() < ARITY {
                    assert!(
                        std::time::Instant::now() < deadline,
                        "the crash world's children never entered their leaf bodies"
                    );
                    tokio::time::sleep(POLL).await;
                }
            });
            drop(runtime);
        })
        .join()
        .expect("the crashing process runs its phase before dying");
    });
}

/// Waits until the crashed process's claims have lapsed, without running
/// anything: a probe whose child host has no openers answers `NoExecutor`,
/// which writes nothing.
async fn until_leases_lapse(
    path: &Path,
    group_key: &str,
    process_env_store: &Arc<dyn lash_core::ProcessExecutionEnvStore>,
) {
    let probe = world(path).await;
    install_child_host(&probe, process_env_store);
    let drain = probe.group_drain();
    drain_until_no_live_lease(&drain, group_key).await;
}

/// Drains until a pass finds nothing left under a live lease, and returns
/// that pass.
#[expect(
    clippy::expect_used,
    reason = "test support: a drain pass over a journaled group runs and the dead process's claims lapse; a refusal panics the harness with its case name by design"
)]
async fn drain_until_no_live_lease(
    drain: &Arc<dyn StoreEffectGroupDrain>,
    group_key: &str,
) -> GroupDrainReport {
    tokio::time::timeout(SETTLE_BUDGET, async {
        loop {
            let report = drain
                .drain_group(group_key, &CancellationToken::new())
                .await
                .expect("a drain pass over the group runs");
            if report
                .children
                .iter()
                .all(|child| !matches!(child.outcome, ChildDrainOutcome::LeaseLive { .. }))
            {
                return report;
            }
            tokio::time::sleep(POLL).await;
        }
    })
    .await
    .expect("the dead process's claims lapse")
}

/// The resolver the reoffering world registers: staged offered executors for
/// its own children, and the real [`ToolChildHost`] for everything else —
/// the routing question about a retained child is answered by production
/// routing, instrumented.
struct DifferentialResolvers {
    /// Executors bound to B's live context, staged under the offered
    /// children's replay keys.
    staged: Mutex<HashMap<String, RuntimeEffectLocalExecutor<'static>>>,
    /// The real child host the retained-children asks fall through to.
    retained: Arc<ToolChildHost>,
    /// The replay keys the driver re-resolved after the staged runners were
    /// discarded — the asks that prove the selector consulted the journal's
    /// retained membership.
    asked: Mutex<Vec<String>>,
}

impl GroupExecutors for DifferentialResolvers {
    fn executor_for(
        &self,
        envelope: &RuntimeEffectEnvelope,
    ) -> Option<RuntimeEffectLocalExecutor<'static>> {
        let replay_key = envelope.invocation.replay_key().to_string();
        if let Some(executor) = self.staged.lock_recover().remove(&replay_key) {
            return Some(executor);
        }
        self.asked.lock_recover().push(replay_key);
        self.retained.executor_for(envelope)
    }
}

// =============================================================================
// The fixture contract
// =============================================================================

/// The two deployments must differ on every axis the checklist rules — a
/// differential that agrees anywhere asserts nothing about that field — and
/// on the request-native axes the checklist does not name.
#[tokio::test]
async fn the_profiles_differ_on_every_axis_and_the_checklist_covers_them() {
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("fixture.db");
    let (a, b, requests_a, requests_b, _env_store) = fixture(&path, "fixture").await;

    for (position, (request_a, request_b)) in requests_a.iter().zip(requests_b.iter()).enumerate() {
        for field in REBIND_FIELDS {
            let value_a = axis_value(&a, request_a, *field);
            let value_b = axis_value(&b, request_b, *field);
            match field.disposition() {
                // A fresh field is minted empty per child — nothing recorded,
                // nothing to differ on.
                RebindDisposition::Fresh => assert_eq!(
                    value_a, value_b,
                    "a Fresh field carries no axis to differ on: {field:?}"
                ),
                RebindDisposition::Rebound | RebindDisposition::Lent => assert_ne!(
                    value_a, value_b,
                    "child {position}: opener deployments must differ on axis \
                     {field:?}: a differential that agrees asserts nothing"
                ),
            }
        }
        // The request-native axes the checklist does not name: the call, the
        // opener arm, the cancellation authority, the enclosing incarnation.
        assert_ne!(
            serde_json::to_string(&request_a.call).expect("the call serializes"),
            serde_json::to_string(&request_b.call).expect("the call serializes"),
            "child {position}: the calls must differ"
        );
        assert_ne!(
            serde_json::to_string(&request_a.scope.opener).expect("the opener serializes"),
            serde_json::to_string(&request_b.scope.opener).expect("the opener serializes"),
            "child {position}: the opener arms must differ"
        );
        // The cancellation authority is host-derived: on one journal every
        // admitted scope derives the same binding, so both requests record
        // it. What must differ — and the gate assertion proves it does — is
        // which opener's live cancellation source the binding resolves to.
        assert_eq!(
            serde_json::to_string(&request_a.cancellation_authority)
                .expect("the authority serializes"),
            serde_json::to_string(&request_b.cancellation_authority)
                .expect("the authority serializes"),
            "child {position}: the cancellation binding is the host's \
             derivation, shared by construction"
        );
        assert_ne!(
            serde_json::to_string(&request_a.enclosing_process)
                .expect("the enclosing process serializes"),
            serde_json::to_string(&request_b.enclosing_process)
                .expect("the enclosing process serializes"),
            "child {position}: the enclosing incarnations must differ"
        );
    }
}

