/// Builds both opener deployments and their requests over one journal path.
///
/// Returns `(a, b, requests_a, requests_b)` with the recorded cancellation
/// authorities this journal's hosts will re-derive.
#[expect(
    clippy::expect_used,
    reason = "test support: the fixture's ids, envs and registrations are valid by construction; a refusal panics the harness with its case name by design"
)]
async fn fixture(
    path: &Path,
    prefix: &str,
) -> (
    OpenerDeployment,
    OpenerDeployment,
    Vec<ToolChildRequest>,
    Vec<ToolChildRequest>,
    Arc<dyn lash_core::ProcessExecutionEnvStore>,
) {
    let group_key = format!("{prefix}-group");
    // One shared environment store carrying both sides' specs: the retained
    // references differ and both resolve on every host.
    let env_store: Arc<dyn lash_core::ProcessExecutionEnvStore> =
        Arc::new(InMemoryProcessExecutionEnvStore::new());
    let owner = ArtifactOwner::host(format!("{prefix}-env"));
    let env_spec_a = ProcessExecutionEnvSpec::new(
        PluginOptions::default(),
        SessionPolicy::new(TurnBudget::Unbounded),
    );
    let env_spec_b = ProcessExecutionEnvSpec::new(
        PluginOptions::default(),
        SessionPolicy::new(TurnBudget::bounded(5)),
    );
    let env_ref_a =
        publish_process_execution_env_for_testing(env_store.as_ref(), &owner, &env_spec_a)
            .await
            .expect("env-a publishes");
    let env_ref_b =
        publish_process_execution_env_for_testing(env_store.as_ref(), &owner, &env_spec_b)
            .await
            .expect("env-b publishes");

    // The recorded cancellation authority is the host's derivation for the
    // admitted scope — identical across hosts over this journal path, so the
    // probe derives what every later host re-derives.
    let probe = world(path).await;
    let admitted_a = AdmittedScope::turn("session-a", "turn-a");
    let admitted_b = AdmittedScope::turn("session-b", "turn-b");
    let binding_a = recorded_cancellation_authority(&probe, &admitted_a).await;
    let binding_b = recorded_cancellation_authority(&probe, &admitted_b).await;
    drop(probe);

    let registry_a = Arc::new(TestLocalProcessRegistry::default());
    let intent_target_a = ProcessId::from(format!("{prefix}-intent-target-a"));
    registry_a
        .register_process_with_observers(
            ProcessRegistration::new(
                intent_target_a.clone(),
                ProcessInput::External {
                    metadata: serde_json::Value::Null,
                },
                RecoveryContract::ExternallyOwned,
                lash_core::ProcessProvenance::host(),
                ProcessLifecyclePolicy::new(ParentScope::Host, OnParentEnd::Abandon),
            )
            .with_extra_event_types(vec![ProcessEventType {
                name: INTENT_EVENT_TYPE.to_string(),
                payload_schema: lash_core::LashSchema::any(),
                semantics: lash_core::ProcessEventSemanticsSpec::default(),
            }]),
            std::slice::from_ref(&SessionId::from("session-a")),
        )
        .await
        .expect("register the intent target on A's registry");
    let registry_b = Arc::new(TestLocalProcessRegistry::default());

    let process_b = ProcessRef::new(
        "process-b",
        ProcessIncarnation::from_registration_sequence(7),
    );
    let scope_a = ExecutionScope::turn("session-a", "turn-a");
    let scope_b = ExecutionScope::turn("session-b", "turn-b");

    let provider_a = Arc::new(ProfileProvider {
        tag: "provider-a",
        park: false,
        impostor: false,
        observation: Arc::new(Observation::default()),
        session_id: SessionId::from("session-a"),
        intent_target: intent_target_a,
    });
    let provider_b = Arc::new(ProfileProvider {
        tag: "provider-b",
        park: false,
        impostor: true,
        observation: Arc::new(Observation::default()),
        session_id: SessionId::from("session-b"),
        intent_target: ProcessId::from("unused-intent-b"),
    });

    let mut turn_context_b = TurnContext::default();
    turn_context_b.insert_plugin_input("differential", "b-turn-context");

    let a = OpenerDeployment {
        plugin_factories: test_code_protocol_factories(),
        plugin_ids: "a:code-protocol",
        provider: Arc::clone(&provider_a),
        tool_registry: Arc::new(
            ToolRegistry::from_tool_provider(Arc::clone(&provider_a) as Arc<dyn ToolProvider>)
                .expect("A's provider registers"),
        ),
        catalog_definitions: leaf_definitions(),
        session_host: Arc::new(MockSessionManager::default()),
        processes: effect_backed_process_service(
            Arc::clone(&registry_a) as Arc<dyn ProcessRegistry>
        ),
        process_registry: registry_a,
        trigger_router: None,
        process_definitions: None,
        process_engines: ProcessEngineRegistry::default(),
        completion_log: Arc::default(),
        completion_canned: canned_completion("a", 41, 7),
        parent_invocation: RuntimeInvocation::effect(
            EffectAddress::new(scope_a.clone(), "parent-a").expect("a valid parent address"),
            RuntimeAttribution::none(),
            "parent-a",
        ),
        env_spec: env_spec_a,
        env_ref: env_ref_a,
        session_id: SessionId::from("session-a"),
        agent_frame_id: FrameNodeId::new("frame-a").expect("a valid frame id"),
        attachment_store: Arc::new(SessionAttachmentStore::in_memory()),
        attachment_source_policy: Arc::new(OpenAttachmentSourcePolicy),
        turn_context: TurnContext::default(),
        clock: Arc::new(SystemClock),
        opener: EffectOpener::for_scope(&admitted_a).expect("a turn scope derives an opener"),
        admitted_scope: admitted_a,
        routing: ToolChildCompletionRouting::Durable,
        enclosing_process: None,
        tag: "a",
    };
    let b = OpenerDeployment {
        plugin_factories: {
            let mut factories = test_code_protocol_factories();
            factories.push(process_engine_plugin_fixture());
            factories
        },
        plugin_ids: "b:code-protocol+fixture-engine",
        provider: Arc::clone(&provider_b),
        tool_registry: Arc::new(
            ToolRegistry::from_tool_provider(Arc::clone(&provider_b) as Arc<dyn ToolProvider>)
                .expect("B's provider registers"),
        ),
        catalog_definitions: b_catalog_definitions(),
        session_host: Arc::new(MockSessionManager::default()),
        processes: effect_backed_process_service(
            Arc::clone(&registry_b) as Arc<dyn ProcessRegistry>
        ),
        process_registry: registry_b,
        trigger_router: Some(TriggerRouter::new(
            Arc::new(InMemoryTriggerStore::default()),
            process_work_wiring_for_registry(
                Arc::new(TestLocalProcessRegistry::default()) as Arc<dyn ProcessRegistry>
            ),
        )),
        process_definitions: Some(Arc::new(InMemoryProcessDefinitionRegistry::default())
            as Arc<dyn lash_core::ProcessDefinitionRegistry>),
        process_engines: process_engine_fixture(),
        completion_log: Arc::default(),
        completion_canned: canned_completion("b", 13, 3),
        parent_invocation: RuntimeInvocation::effect(
            EffectAddress::new(scope_b.clone(), "parent-b").expect("a valid parent address"),
            RuntimeAttribution::none(),
            "parent-b",
        ),
        env_spec: env_spec_b,
        env_ref: env_ref_b,
        session_id: SessionId::from("session-b"),
        agent_frame_id: FrameNodeId::new("frame-b").expect("a valid frame id"),
        attachment_store: Arc::new(SessionAttachmentStore::in_memory()),
        attachment_source_policy: Arc::new(OpenAttachmentSourcePolicy),
        turn_context: turn_context_b,
        clock: Arc::new(TestClock::new(1_700_000_000_000)),
        opener: EffectOpener::process(process_b.clone()),
        admitted_scope: admitted_b,
        routing: ToolChildCompletionRouting::ProcessLifetime {
            issuer: TurnControlBindingId::new("binding-b-issuer").expect("a valid binding id"),
        },
        enclosing_process: Some(process_b),
        tag: "b",
    };

    let requests_a = requests_a(&a, &group_key, binding_a);
    let requests_b = requests_b(&b, &group_key, binding_b);
    (a, b, requests_a, requests_b, env_store)
}

/// The differential itself.
///
/// Phase 1 claims the four retained children under A's live opener on a host
/// that is then destroyed — claimed, journaled, owned by nobody. Phase 2
/// reopens under B's live opener offering the same replay keys under B's own
/// requests, staged with executors bound to B's live context; the honest
/// selector discards them on the envelope check, and with A's opener absent
/// the retained children run nowhere. Phase 3 registers *both* opener
/// contexts live on one recovering host and asserts every observable a
/// retained child can produce belongs to A.
#[tokio::test]
async fn a_child_runs_under_the_opener_that_admitted_it_not_the_one_reoffering_its_key() {
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("two-opener.db");
    let prefix = format!("two-opener-{:x}", fastrand::u64(..));
    let admitted = AdmittedScope::runtime_operation(format!("{prefix}-scope"));
    let scope = admitted.scope().clone();
    let key = format!("{prefix}-group");
    let (a, b, requests_a, requests_b, env_store) = fixture(&path, &prefix).await;

    // Phase 1: A's children are claimed and in flight when the process dies.
    let observation_crash = Arc::new(Observation::default());
    let park_provider = Arc::new(ProfileProvider {
        tag: "provider-a",
        park: true,
        impostor: false,
        observation: Arc::clone(&observation_crash),
        session_id: a.session_id.clone(),
        intent_target: a.provider.intent_target.clone(),
    });
    crash_opening(
        &path,
        group(&scope, &key, &requests_a),
        admitted.clone(),
        &a,
        park_provider,
        Arc::clone(&env_store),
        observation_crash,
    );
    until_leases_lapse(&path, &key, &env_store).await;

    // Phase 2: B's world. The composite stages executors bound to B's live
    // context for the offered keys; the honest selector discards them
    // because the offered envelopes differ from the retained bytes, and the
    // retained asks fall through to the real child host — where A's opener
    // is absent — and answer `None`.
    let world_b = world(&path).await;
    let dyn_b: Arc<dyn EffectHost> = Arc::clone(&world_b) as Arc<dyn EffectHost>;
    let child_host_b = Arc::new(ToolChildHost::new(&dyn_b, Arc::clone(&env_store)));
    let resolvers = Arc::new(DifferentialResolvers {
        staged: Mutex::new(HashMap::new()),
        retained: Arc::clone(&child_host_b),
        asked: Mutex::new(Vec::new()),
    });
    world_b
        .register_group_executors(Arc::clone(&resolvers) as Arc<dyn GroupExecutors>)
        .expect("a freshly opened host has no resolver yet");
    let coop_b_phase2 = CancellationToken::new();
    let (_guard_b2, context_b) = b.register_opener(
        &world_b,
        &child_host_b,
        Arc::clone(&b.provider) as Arc<dyn ToolProvider>,
        &coop_b_phase2,
    );
    let group_b = group(&scope, &key, &requests_b);
    for child in group_b.children() {
        resolvers.staged.lock_recover().insert(
            child.invocation.replay_key().to_string(),
            child_host_b.executor_bound_to(context_b.clone()),
        );
    }
    let scoped_b = world_b
        .scoped(admitted.clone())
        .expect("the group scope binds");
    let mut handle_b = scoped_b
        .controller()
        .open_effect_group(group_b)
        .await
        .expect("a reopen tolerates a child this host cannot run");

    assert!(
        tokio::time::timeout(
            ABSENCE_BUDGET,
            scoped_b
                .controller()
                .await_next_settlement(&mut handle_b, CancellationToken::new()),
        )
        .await
        .is_err(),
        "no settlement arrives: nothing B resolved may run a retained child"
    );
    assert!(
        b.provider.observation.executions().is_empty(),
        "B's provider ran nothing: {:?}",
        b.provider.observation.executions()
    );
    let mut asked = resolvers.asked.lock_recover().clone();
    asked.sort();
    let mut expected_asks = (0..ARITY)
        .map(|position| child_key(&key, position))
        .collect::<Vec<_>>();
    expected_asks.sort();
    assert_eq!(
        asked, expected_asks,
        "the routing question the reopen asks is about the retained \
         children, once each — matching on the key alone would ask nothing"
    );
    scoped_b
        .controller()
        .close_effect_group(handle_b, RUN)
        .await
        .expect("the observing handle closes");
    drop(_guard_b2);
    drop(scoped_b);

    // Phase 3: an honest recovery. Both opener contexts are live in the same
    // real ToolChildHost — A's serving provider and B's impostor provider —
    // so which context a retained child binds is decided by its recorded
    // opener alone. Every observable must be A's.
    let world_c = world(&path).await;
    let installed_c = install_child_host(&world_c, &env_store);
    let coop_a = CancellationToken::new();
    let coop_b = CancellationToken::new();
    let _guard_a = a
        .register_opener(
            &world_c,
            &installed_c,
            Arc::clone(&a.provider) as Arc<dyn ToolProvider>,
            &coop_a,
        )
        .0;
    let _guard_b = b
        .register_opener(
            &world_c,
            &installed_c,
            Arc::clone(&b.provider) as Arc<dyn ToolProvider>,
            &coop_b,
        )
        .0;

    let scoped_c = world_c
        .scoped(admitted.clone())
        .expect("the group scope binds");
    let mut handle = scoped_c
        .controller()
        .open_effect_group(group(&scope, &key, &requests_a))
        .await
        .expect("an honest reopen runs the retained children");

    // The deferred child parks on a completion key minted under A's recorded
    // routing; the issuer's scope is A's admitted scope.
    let defer_call = format!("{key}-call-{}", position_of(TOOL_DEFER));
    let parked = a.provider.observation.parked_key(&defer_call).await;
    assert_eq!(
        parked.scope,
        ExecutionScope::turn("session-a", "turn-a"),
        "the deferred child's completion key is issued under A's scope"
    );
    world_c
        .resolve_await_event(
            &parked,
            Resolution::Ok(serde_json::json!({ "resolved": "by-a" })),
        )
        .await
        .expect("the parked child's key resolves");

    // The gate child parks on the resolved opener's cooperative token.
    tokio::time::timeout(SETTLE_BUDGET, async {
        while a.provider.observation.gate_entered.load(Ordering::SeqCst) == 0 {
            tokio::time::sleep(POLL).await;
        }
    })
    .await
    .expect("the gate child entered its body");

    // Settle ranks 0–2 while the gate child waits on A's gate.
    let mut settlements = Vec::new();
    for rank in 0..ARITY - 1 {
        let settlement = tokio::time::timeout(
            SETTLE_BUDGET,
            scoped_c
                .controller()
                .await_next_settlement(&mut handle, CancellationToken::new()),
        )
        .await
        .unwrap_or_else(|_| panic!("settlement for rank {rank} never arrived"))
        .unwrap_or_else(|error| panic!("settlement for rank {rank} failed to be served: {error}"));
        settlements.push(settlement);
    }

    // B's gate does not stop A's child; A's does.
    coop_b.cancel();
    assert!(
        tokio::time::timeout(
            ABSENCE_BUDGET,
            scoped_c
                .controller()
                .await_next_settlement(&mut handle, CancellationToken::new()),
        )
        .await
        .is_err(),
        "cancelling B's cooperative token does not stop a child admitted under A"
    );
    coop_a.cancel();
    let gate_settlement = tokio::time::timeout(
        SETTLE_BUDGET,
        scoped_c
            .controller()
            .await_next_settlement(&mut handle, CancellationToken::new()),
    )
    .await
    .expect("cancelling A's cooperative token settles the gate child")
    .expect("the gate settlement is served");
    settlements.push(gate_settlement);
    // Settlements are served in settle order, not rank order — index by the
    // position each reports, the way the journal names it.
    settlements.sort_by_key(|settlement| settlement.position);

    // ---- Every observable is A's ----
    let executions = a.provider.observation.executions();
    assert_eq!(
        executions.len(),
        ARITY + 1,
        "A's provider ran every retained leaf body exactly once, plus the \
         spend leaf's retried attempt: {executions:?}"
    );
    assert!(
        executions
            .iter()
            .all(|execution| execution.session_id == "session-a"),
        "every execution was attributed to A's session: {executions:?}"
    );
    let observe = executions
        .iter()
        .find(|execution| execution.tool == "a_observe")
        .unwrap_or_else(|| panic!("the observe leaf ran: {executions:?}"));
    assert_eq!(
        observe.execution_binding,
        serde_json::json!({ "opener": "a" }),
        "the granted leaf executed under the recorded grant's binding"
    );
    assert!(
        executions
            .iter()
            .all(|execution| execution.enclosing_process.is_none()),
        "every attempt context was built from the retained request — A's \
         children record no enclosing process: {executions:?}"
    );
    let mut spend_attempts = executions
        .iter()
        .filter(|execution| execution.tool == "a_spend")
        .map(|execution| execution.attempt)
        .collect::<Vec<_>>();
    spend_attempts.sort_unstable();
    assert_eq!(
        spend_attempts,
        vec![1, 2],
        "the spend leaf ran its failed attempt and its retry: {executions:?}"
    );
    assert!(
        b.provider.observation.executions().is_empty(),
        "B's provider never ran: {:?}",
        b.provider.observation.executions()
    );

    // Billing: only A's completion client was billed, and the ledger on the
    // spend settlement carries A's canned usage — twice, once per attempt.
    assert_eq!(
        a.completion_log.lock_recover().len(),
        2,
        "A's completion client billed once per spend attempt: {:?}",
        a.completion_log.lock_recover()
    );
    assert!(
        b.completion_log.lock_recover().is_empty(),
        "B's completion client was never billed"
    );
    let spend = &settlements[position_of(TOOL_SPEND)];
    let Ok(RuntimeEffectOutcome::ToolInvocation {
        settlement,
        outcome,
    }) = &spend.outcome
    else {
        panic!("the spend child settles a tool invocation: {spend:?}")
    };
    assert!(
        matches!(
            outcome.record.output.outcome,
            lash_core::ToolCallOutcome::Success(_)
        ),
        "the spend child settled successfully: {outcome:?}"
    );
    let billed: i64 = settlement
        .usage
        .iter()
        .map(|delta| delta.usage.input_tokens)
        .sum();
    assert_eq!(
        billed, 82,
        "the ledger carries A's canned usage across both attempts"
    );
    assert!(
        settlement
            .usage
            .iter()
            .all(|delta| delta.llm_call_id == LlmCallId("a-direct-call".to_string())),
        "every billed delta names A's call: {:?}",
        settlement.usage
    );
    let mut attempts = settlement
        .usage
        .iter()
        .map(|delta| delta.attempt)
        .collect::<Vec<_>>();
    attempts.sort_unstable();
    assert_eq!(
        attempts,
        vec![1, 2],
        "the failed first attempt's spend is journaled beside the second's"
    );

    // Possession and fact buffers: the intents realized on A's registry, and
    // the settlement carries the started process plus the event outcome.
    assert_eq!(
        settlement.possession.len(),
        1,
        "the started process rides the settlement's possession"
    );
    let a_events = a.process_registry.raw_state_for_testing().await.events;
    assert!(
        a_events
            .iter()
            .any(|(_, event)| event.event_type == INTENT_EVENT_TYPE),
        "the declared process event landed on A's registry: {a_events:?}"
    );
    let b_events = b.process_registry.raw_state_for_testing().await.events;
    assert!(
        b_events.is_empty(),
        "B's registry received no intent realization: {b_events:?}"
    );

    // The gate settlement carries A's cancel: the cooperative token that
    // stopped the child was the resolved opener's.
    let gate = &settlements[position_of(TOOL_GATE)];
    let Ok(RuntimeEffectOutcome::ToolInvocation {
        outcome: gate_outcome,
        ..
    }) = &gate.outcome
    else {
        panic!("the gate child settles a tool invocation: {gate:?}")
    };
    assert!(
        format!("{:?}", gate_outcome.record.output).contains("cooperative gate"),
        "the gate child settled as cancelled under A's token: {gate_outcome:?}"
    );

    // The deferred settlement carries the out-of-band resolution issued
    // under A's completion authority.
    let deferred = &settlements[position_of(TOOL_DEFER)];
    let Ok(RuntimeEffectOutcome::ToolInvocation {
        outcome: deferred_outcome,
        ..
    }) = &deferred.outcome
    else {
        panic!("the deferred child settles a tool invocation: {deferred:?}")
    };
    assert!(
        format!("{:?}", deferred_outcome.record.output).contains("by-a"),
        "the deferred child settled with the resolution issued under A's \
         completion routing: {deferred_outcome:?}"
    );

    scoped_c
        .controller()
        .close_effect_group(handle, RUN)
        .await
        .expect("the caller closes");
}

/// The oracle is only worth trusting if it goes red against the leak it
/// names. The leak is injected at the production selector: this host's
/// offered-child selection is flipped to `KeyOnly`, so the executors staged
/// for B's offered children — real runners bound to B's live context — are
/// reused for the retained children on a replay-key match alone. The
/// resolver stays honest; the leak is in the selector, exactly where the
/// fix holds it closed.
#[tokio::test]
async fn the_oracle_goes_red_when_offered_executors_match_by_key_alone() {
    let dir = tempfile::tempdir().expect("tempdir");
    let path = dir.path().join("two-opener-mutant.db");
    let prefix = format!("two-opener-mutant-{:x}", fastrand::u64(..));
    let admitted = AdmittedScope::runtime_operation(format!("{prefix}-scope"));
    let scope = admitted.scope().clone();
    let key = format!("{prefix}-group");
    let (a, b, requests_a, requests_b, env_store) = fixture(&path, &prefix).await;

    let observation_crash = Arc::new(Observation::default());
    let park_provider = Arc::new(ProfileProvider {
        tag: "provider-a",
        park: true,
        impostor: false,
        observation: Arc::clone(&observation_crash),
        session_id: a.session_id.clone(),
        intent_target: a.provider.intent_target.clone(),
    });
    crash_opening(
        &path,
        group(&scope, &key, &requests_a),
        admitted.clone(),
        &a,
        park_provider,
        Arc::clone(&env_store),
        observation_crash,
    );
    until_leases_lapse(&path, &key, &env_store).await;

    // B's world, poisoned at the selector: the staged B-bound executors are
    // reused for the retained children on a replay-key match alone.
    let world_b = world(&path).await;
    world_b
        .replay_driver()
        .set_offered_child_selection(OfferedChildSelection::KeyOnly);
    let dyn_b: Arc<dyn EffectHost> = Arc::clone(&world_b) as Arc<dyn EffectHost>;
    let child_host_b = Arc::new(ToolChildHost::new(&dyn_b, Arc::clone(&env_store)));
    let resolvers = Arc::new(DifferentialResolvers {
        staged: Mutex::new(HashMap::new()),
        retained: Arc::clone(&child_host_b),
        asked: Mutex::new(Vec::new()),
    });
    world_b
        .register_group_executors(Arc::clone(&resolvers) as Arc<dyn GroupExecutors>)
        .expect("a freshly opened host has no resolver yet");
    let coop_b = CancellationToken::new();
    let (_guard_b, context_b) = b.register_opener(
        &world_b,
        &child_host_b,
        Arc::clone(&b.provider) as Arc<dyn ToolProvider>,
        &coop_b,
    );
    let group_b = group(&scope, &key, &requests_b);
    for child in group_b.children() {
        resolvers.staged.lock_recover().insert(
            child.invocation.replay_key().to_string(),
            child_host_b.executor_bound_to(context_b.clone()),
        );
    }
    let scoped_b = world_b
        .scoped(admitted.clone())
        .expect("the group scope binds");
    let mut handle = scoped_b
        .controller()
        .open_effect_group(group_b)
        .await
        .expect("the poisoned reopen runs");

    // Every green-path assertion inverts: B's impostor provider executes the
    // retained children under B's context, and settlements arrive.
    tokio::time::timeout(SETTLE_BUDGET, async {
        while b.provider.observation.executions().is_empty() {
            tokio::time::sleep(POLL).await;
        }
    })
    .await
    .expect(
        "under the key-only selector B's provider runs the retained children — \
         the oracle's `B's provider ran nothing` assertion fails here",
    );
    let settlement = tokio::time::timeout(
        SETTLE_BUDGET,
        scoped_b
            .controller()
            .await_next_settlement(&mut handle, CancellationToken::new()),
    )
    .await;
    assert!(
        settlement.is_ok(),
        "under the key-only selector a retained child settles — the oracle's \
         `no settlement arrives` assertion fails here"
    );
    assert!(
        b.provider
            .observation
            .executions()
            .iter()
            .all(|execution| execution.tool.starts_with("a_")),
        "B's impostor impl served A's retained leaf calls: {:?}",
        b.provider.observation.executions()
    );
    assert!(
        a.provider.observation.executions().is_empty(),
        "A's provider never ran — the work happened under B's context"
    );

    drop(_guard_b);
    scoped_b
        .controller()
        .close_effect_group(handle, RUN)
        .await
        .expect("the caller closes");
}
